"""Lay students out in seating rows."""

from typing import List, Sequence

from rosterkit.models import Student
from rosterkit.errors import ProjectError

def _check(students, per_row):
    if per_row <= 0:
        raise ProjectError("seats per row must be positive")
    if not students:
        raise ProjectError("no students to seat")

def _sort_key(student):
    return (
        student.last_name.casefold(),
        student.first_name.casefold(),
        student.student_id
    )

def _row_line(number, row):
    names = " | ".join(s.display_name for s in row)
    return f"Row {number}: {names}"

# ---
def seat_rows(
    students: Sequence[Student], per_row: int
) -> List[str]:
    """One text line per row, sorted by last name."""
    _check(students, per_row)
    ordered = sorted(students, key=_sort_key)
    rows = [
        ordered[i:i + per_row]
        for i in range(0, len(ordered), per_row)
    ]
    return [_row_line(n, r) for n, r in enumerate(rows, 1)]

